using System.Text.Json;
using Microsoft.Diagnostics.Symbols;
using Microsoft.Diagnostics.Tracing;
using Microsoft.Diagnostics.Tracing.Etlx;
using Microsoft.Diagnostics.Tracing.Parsers.Kernel;

// Throwaway decoder for artifacts generated by the Windows profiler probe.
var artifacts = Path.GetFullPath(args[0]);
var executableName = args[1];
var decoded = new List<object>();
var workloadSamples = 0;
foreach (var etl in Directory.EnumerateFiles(Path.Combine(artifacts, "session"), "*.etl", SearchOption.AllDirectories))
{
    Console.WriteLine($"Reading {etl}");
    using var trace = TraceLog.OpenOrConvert(etl, new TraceLogOptions { ConversionLog = Console.Out });
    Console.WriteLine($"Events: {trace.EventCount}");
    foreach (var group in trace.Events.GroupBy(e => $"{e.ProviderName}/{e.EventName}").OrderByDescending(g => g.Count()).Take(15))
        Console.WriteLine($"  {group.Key}: {group.Count()}");
    using var symbols = new SymbolReader(Console.Out, artifacts);
    // The probe built these PDBs itself. Keep this trust decision in the experiment.
    symbols.SecurityCheck = _ => true;
    symbols.Options = SymbolReaderOptions.CacheOnly;
    foreach (var process in trace.Processes)
    {
        var samples = process.EventsInProcess.ByEventType<SampledProfileTraceData>().Count();
        if (samples > 0)
            Console.WriteLine($"Process {process.ProcessID}: {process.ImageFileName}, {samples} CPU samples");
        if (!string.Equals(Path.GetFileName(process.ImageFileName), executableName, StringComparison.OrdinalIgnoreCase))
            continue;
        foreach (var module in process.LoadedModules)
        {
            if (string.Equals(Path.GetFileName(module.ModuleFile.FilePath), executableName, StringComparison.OrdinalIgnoreCase))
                trace.CodeAddresses.LookupSymbolsForModule(symbols, module.ModuleFile);
        }
        foreach (var sample in process.EventsInProcess.ByEventType<SampledProfileTraceData>())
        {
            var frames = new List<string>();
            for (var frame = sample.CallStack(); frame != null; frame = frame.Caller)
            {
                var address = frame.CodeAddress;
                frames.Add($"{address.ModuleFile?.Name}!{(string.IsNullOrEmpty(address.FullMethodName) ? $"0x{address.Address:x}" : address.FullMethodName)}");
            }
            if (frames.Any(frame => frame.Contains("workload", StringComparison.Ordinal)))
                workloadSamples++;
            decoded.Add(new { file = Path.GetFileName(etl), sample.ProcessID, sample.ThreadID, sample.TimeStampRelativeMSec, frames });
        }
    }
}
File.WriteAllText(Path.Combine(artifacts, "samples.json"), JsonSerializer.Serialize(new { samples = decoded, workloadSamples }, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine($"Decoded {decoded.Count} CPU samples, {workloadSamples} with workload symbols.");
return workloadSamples > 0 ? 0 : 1;
